"use client";

import { useReducedMotion } from "motion/react";
import { useEffect, useRef, useState, type CSSProperties } from "react";
import { GSAP_EASE_NAMES } from "./gsap-ease-names";
import { gsap, registerGsap } from "./gsap";
import { FINE_POINTER_QUERY, shouldEnablePointerAccent } from "./motion-policy";
import {
  POINTER_ACCENT_DEFAULTS,
  pointerAccentHoverTransform,
  pointerAccentLayoutSize,
  pointerAccentZIndexVar,
  pointerDeformation,
  pointerHoverCoverScale,
  pointerRotationDeg,
  pointerSpeedPxPerMs,
  resolvePointerAccentOptions,
  type PointerAccentOptions,
} from "./pointer-accent-options";
import { useMotionProfile } from "./use-motion-profile";

export type { PointerAccentOptions } from "./pointer-accent-options";

function closestHoverTarget(
  node: EventTarget | null,
  hoverSelectors: string,
  textSelectors: string,
): { el: Element; mode: "text" | "interactive" } | null {
  if (!(node instanceof Element)) {
    return null;
  }
  try {
    if (node.closest("[data-pointer-accent]")) {
      return null;
    }
    const text = textSelectors.trim() ? node.closest(textSelectors) : null;
    if (text) {
      return { el: text, mode: "text" };
    }
    const interactive = hoverSelectors.trim() ? node.closest(hoverSelectors) : null;
    if (interactive) {
      return { el: interactive, mode: "interactive" };
    }
  } catch {
    return null;
  }
  return null;
}

export function PointerAccent(options: PointerAccentOptions = {}) {
  const reduce = useReducedMotion();
  const profile = useMotionProfile();
  const profileRef = useRef(profile);
  profileRef.current = profile;
  const resolved = resolvePointerAccentOptions(options);
  const [finePointer, setFinePointer] = useState(false);
  const outerRef = useRef<HTMLDivElement | null>(null);
  const innerRef = useRef<SVGSVGElement | null>(null);
  const layoutSize = pointerAccentLayoutSize(
    resolved.size,
    resolved.hoverGrow,
    resolved.hoverScaleMax,
  );
  const restScale = pointerAccentHoverTransform(
    1,
    resolved.hoverGrow,
    resolved.hoverScaleMax,
  );

  useEffect(() => {
    const media = window.matchMedia(FINE_POINTER_QUERY);
    const update = () => {
      setFinePointer(media.matches);
    };
    update();
    media.addEventListener("change", update);
    return () => {
      media.removeEventListener("change", update);
    };
  }, []);

  const allowed = shouldEnablePointerAccent({
    enabled: resolved.enabled,
    reduce,
    finePointer,
  });

  useEffect(() => {
    if (!allowed) {
      return;
    }
    const outer = outerRef.current;
    const inner = innerRef.current;
    if (!outer || !inner) {
      return;
    }

    registerGsap();
    const settleEase = GSAP_EASE_NAMES.settle;
    const settleDuration = profileRef.current.duration.base;
    const followEase = resolved.ease;
    const xTo = gsap.quickTo(outer, "x", { duration: resolved.lag, ease: followEase });
    const yTo = gsap.quickTo(outer, "y", { duration: resolved.lag, ease: followEase });
    const hoverScaleXTo = gsap.quickTo(outer, "scaleX", {
      duration: settleDuration,
      ease: settleEase,
    });
    const hoverScaleYTo = gsap.quickTo(outer, "scaleY", {
      duration: settleDuration,
      ease: settleEase,
    });
    const opacityTo = gsap.quickTo(outer, "opacity", {
      duration: settleDuration,
      ease: settleEase,
    });
    const rotateTo = gsap.quickTo(inner, "rotation", {
      duration: resolved.lag,
      ease: followEase,
    });
    const scaleXTo = gsap.quickTo(inner, "scaleX", {
      duration: settleDuration,
      ease: settleEase,
    });
    const scaleYTo = gsap.quickTo(inner, "scaleY", {
      duration: settleDuration,
      ease: settleEase,
    });

    gsap.set(outer, {
      xPercent: -50,
      yPercent: -50,
      x: 0,
      y: 0,
      scaleX: restScale,
      scaleY: restScale,
      opacity: 0,
    });
    gsap.set(inner, {
      rotation: 0,
      scaleX: 1,
      scaleY: 1,
    });

    let lastX = 0;
    let lastY = 0;
    let lastTime = 0;
    let hoverEl: Element | null = null;
    let settleCall: ReturnType<typeof gsap.delayedCall> | null = null;

    function restShape() {
      if (hoverEl) {
        return;
      }
      scaleXTo(1);
      scaleYTo(1);
    }

    function applyHoverCover(el: Element) {
      const rect = el.getBoundingClientRect();
      const cover = pointerAccentHoverTransform(
        pointerHoverCoverScale(
          resolved.size,
          rect.width,
          rect.height,
          resolved.hoverScaleMax,
        ),
        resolved.hoverGrow,
        resolved.hoverScaleMax,
      );
      hoverScaleXTo(cover);
      hoverScaleYTo(cover);
      scaleXTo(1);
      scaleYTo(1);
    }

    function clearHover() {
      hoverEl = null;
      hoverScaleXTo(restScale);
      hoverScaleYTo(restScale);
    }

    function hide() {
      settleCall?.kill();
      opacityTo(0);
      clearHover();
      scaleXTo(1);
      scaleYTo(1);
    }

    function onMove(event: PointerEvent) {
      if (
        !shouldEnablePointerAccent({
          enabled: resolved.enabled,
          reduce,
          finePointer: true,
          pointerType: event.pointerType,
        })
      ) {
        hide();
        return;
      }

      const now = event.timeStamp || performance.now();
      const x = event.clientX + resolved.offsetX;
      const y = event.clientY + resolved.offsetY;
      const elapsed = lastTime === 0 ? 0 : now - lastTime;
      const dx = lastTime === 0 ? 0 : x - lastX;
      const dy = lastTime === 0 ? 0 : y - lastY;
      const speed = pointerSpeedPxPerMs(Math.hypot(dx, dy), elapsed);
      const deformation = pointerDeformation(
        speed,
        resolved.stretch,
        resolved.maxStretch,
      );

      xTo(x);
      yTo(y);

      if (!hoverEl && speed >= POINTER_ACCENT_DEFAULTS.restSpeed) {
        rotateTo(pointerRotationDeg(dx, dy));
        scaleXTo(deformation.scaleX);
        scaleYTo(deformation.scaleY);
      } else if (!hoverEl) {
        restShape();
      }

      lastX = x;
      lastY = y;
      lastTime = now;

      opacityTo(resolved.opacity);

      settleCall?.kill();
      settleCall = gsap.delayedCall(0.12, restShape);
    }

    function onPointerOver(event: PointerEvent) {
      if (!resolved.hoverGrow) {
        return;
      }
      const next = closestHoverTarget(
        event.target,
        resolved.hoverSelectors,
        resolved.textSelectors,
      );
      if (!next) {
        return;
      }
      hoverEl = next.el;
      applyHoverCover(next.el);
    }

    function onPointerOut(event: PointerEvent) {
      if (!hoverEl) {
        return;
      }
      const related = event.relatedTarget;
      if (related instanceof Node && hoverEl.contains(related)) {
        return;
      }
      const still = closestHoverTarget(
        related,
        resolved.hoverSelectors,
        resolved.textSelectors,
      );
      if (still && still.el === hoverEl) {
        return;
      }
      clearHover();
    }

    function onLeave(event: PointerEvent | MouseEvent) {
      const next = event.relatedTarget;
      if (next instanceof Node && document.documentElement.contains(next)) {
        return;
      }
      hide();
    }

    function onBlur() {
      hide();
    }

    window.addEventListener("pointermove", onMove, { passive: true });
    document.addEventListener("pointerover", onPointerOver, { passive: true });
    document.addEventListener("pointerout", onPointerOut, { passive: true });
    document.documentElement.addEventListener("pointerleave", onLeave);
    document.documentElement.addEventListener("mouseleave", onLeave);
    window.addEventListener("blur", onBlur);

    return () => {
      window.removeEventListener("pointermove", onMove);
      document.removeEventListener("pointerover", onPointerOver);
      document.removeEventListener("pointerout", onPointerOut);
      document.documentElement.removeEventListener("pointerleave", onLeave);
      document.documentElement.removeEventListener("mouseleave", onLeave);
      window.removeEventListener("blur", onBlur);
      settleCall?.kill();
      gsap.killTweensOf(outer);
      gsap.killTweensOf(inner);
    };
  }, [
    allowed,
    reduce,
    resolved.blendMode,
    resolved.color,
    resolved.ease,
    resolved.enabled,
    resolved.hoverGrow,
    resolved.hoverScaleMax,
    resolved.hoverSelectors,
    resolved.lag,
    resolved.maxStretch,
    resolved.offsetX,
    resolved.offsetY,
    resolved.opacity,
    resolved.shape,
    resolved.size,
    resolved.stretch,
    resolved.textSelectors,
    restScale,
  ]);

  if (!allowed) {
    return null;
  }

  return (
    <div
      ref={outerRef}
      aria-hidden="true"
      data-pointer-accent=""
      data-testid="pointer-accent"
      data-shape={resolved.shape}
      className={resolved.className}
      style={{
        position: "fixed",
        top: 0,
        left: 0,
        width: layoutSize,
        height: layoutSize,
        zIndex: pointerAccentZIndexVar(resolved.zIndex),
        pointerEvents: "none",
        mixBlendMode: resolved.blendMode as CSSProperties["mixBlendMode"],
        transform: `translate(-50%, -50%) scale(${restScale})`,
        transformOrigin: "center center",
        opacity: 0,
        willChange: "transform, opacity",
      }}
    >
      <svg
        ref={innerRef}
        data-pointer-accent-inner=""
        viewBox="0 0 100 100"
        overflow="visible"
        style={{
          display: "block",
          width: "100%",
          height: "100%",
          willChange: "transform",
        }}
      >
        {resolved.shape === "square" ? (
          <rect x="0" y="0" width="100" height="100" rx="8" fill={resolved.color} />
        ) : resolved.shape === "ring" ? (
          <circle
            cx="50"
            cy="50"
            r="49"
            fill="none"
            stroke={resolved.color}
            strokeWidth="2"
          />
        ) : (
          <circle cx="50" cy="50" r="50" fill={resolved.color} />
        )}
      </svg>
    </div>
  );
}

import { clamp } from "./clamp";
import type { TweenIntent } from "./profiles/types";
import { TWEEN_INTENTS } from "./profiles/types";
import { GSAP_EASE_NAMES } from "./gsap-ease-names";

export const POINTER_ACCENT_SHAPES = ["circle", "square", "ring"] as const;
export const POINTER_ACCENT_Z_INDEX = [
  "base",
  "raised",
  "sticky",
  "overlay",
  "dialog",
  "toast",
  "debug",
] as const;
export const POINTER_ACCENT_BLEND_MODES = [
  "normal",
  "multiply",
  "screen",
  "overlay",
  "darken",
  "lighten",
  "color-dodge",
  "color-burn",
  "difference",
  "exclusion",
  "hue",
  "saturation",
  "color",
  "luminosity",
  "plus-lighter",
] as const;

export type PointerAccentShape = (typeof POINTER_ACCENT_SHAPES)[number];
export type PointerAccentZIndex = (typeof POINTER_ACCENT_Z_INDEX)[number];
export type PointerAccentBlendMode = (typeof POINTER_ACCENT_BLEND_MODES)[number];

export type PointerAccentOptions = {
  enabled?: boolean;
  size?: number;
  color?: string;
  opacity?: number;
  shape?: PointerAccentShape;
  lag?: number;
  ease?: TweenIntent | string;
  stretch?: number;
  maxStretch?: number;
  offsetX?: number;
  offsetY?: number;
  blendMode?: PointerAccentBlendMode | string;
  zIndex?: PointerAccentZIndex;
  className?: string;
  hoverGrow?: boolean;
  hoverSelectors?: string;
  textSelectors?: string;
  hoverScaleMax?: number;
};

export type ResolvedPointerAccentOptions = {
  enabled: boolean;
  size: number;
  color: string;
  opacity: number;
  shape: PointerAccentShape;
  lag: number;
  ease: string;
  stretch: number;
  maxStretch: number;
  offsetX: number;
  offsetY: number;
  blendMode: string;
  zIndex: PointerAccentZIndex;
  className?: string;
  hoverGrow: boolean;
  hoverSelectors: string;
  textSelectors: string;
  hoverScaleMax: number;
};

export const POINTER_ACCENT_DEFAULTS = {
  enabled: false,
  size: 14,
  sizeMin: 4,
  sizeMax: 96,
  color: "oklch(0.97 0.004 250)",
  opacity: 1,
  opacityMin: 0.08,
  opacityMax: 1,
  shape: "circle" as PointerAccentShape,
  lag: 0.4,
  lagMin: 0.04,
  lagMax: 0.85,
  ease: "power3.out",
  stretch: 0.2,
  stretchMin: 0,
  stretchMax: 1.5,
  maxStretch: 0.6,
  maxStretchMin: 0,
  maxStretchMax: 1.2,
  offsetX: 0,
  offsetY: 0,
  offsetMax: 48,
  blendMode: "difference" as PointerAccentBlendMode,
  zIndex: "debug" as PointerAccentZIndex,
  speedMax: 2.4,
  restSpeed: 0.08,
  hoverGrow: true,
  hoverSelectors: "a, button, [data-pointer-accent-hover], [data-slot=button]",
  textSelectors: "[data-pointer-accent-text]",
  hoverScaleMax: 1.5,
  hoverScaleMaxMin: 1,
  hoverScaleMaxMax: 24,
  hoverPadding: 1.18,
};

export function resolvePointerEase(ease: TweenIntent | string | undefined): string {
  const value = ease ?? POINTER_ACCENT_DEFAULTS.ease;
  if ((TWEEN_INTENTS as readonly string[]).includes(value)) {
    return GSAP_EASE_NAMES[value as TweenIntent];
  }
  return value;
}

export function resolvePointerAccentOptions(
  options: PointerAccentOptions = {},
): ResolvedPointerAccentOptions {
  return {
    enabled: options.enabled ?? POINTER_ACCENT_DEFAULTS.enabled,
    size: clamp(
      options.size ?? POINTER_ACCENT_DEFAULTS.size,
      POINTER_ACCENT_DEFAULTS.sizeMin,
      POINTER_ACCENT_DEFAULTS.sizeMax,
    ),
    color: options.color ?? POINTER_ACCENT_DEFAULTS.color,
    opacity: clamp(
      options.opacity ?? POINTER_ACCENT_DEFAULTS.opacity,
      POINTER_ACCENT_DEFAULTS.opacityMin,
      POINTER_ACCENT_DEFAULTS.opacityMax,
    ),
    shape: options.shape ?? POINTER_ACCENT_DEFAULTS.shape,
    lag: clamp(
      options.lag ?? POINTER_ACCENT_DEFAULTS.lag,
      POINTER_ACCENT_DEFAULTS.lagMin,
      POINTER_ACCENT_DEFAULTS.lagMax,
    ),
    ease: resolvePointerEase(options.ease),
    stretch: clamp(
      options.stretch ?? POINTER_ACCENT_DEFAULTS.stretch,
      POINTER_ACCENT_DEFAULTS.stretchMin,
      POINTER_ACCENT_DEFAULTS.stretchMax,
    ),
    maxStretch: clamp(
      options.maxStretch ?? POINTER_ACCENT_DEFAULTS.maxStretch,
      POINTER_ACCENT_DEFAULTS.maxStretchMin,
      POINTER_ACCENT_DEFAULTS.maxStretchMax,
    ),
    offsetX: clamp(
      options.offsetX ?? POINTER_ACCENT_DEFAULTS.offsetX,
      -POINTER_ACCENT_DEFAULTS.offsetMax,
      POINTER_ACCENT_DEFAULTS.offsetMax,
    ),
    offsetY: clamp(
      options.offsetY ?? POINTER_ACCENT_DEFAULTS.offsetY,
      -POINTER_ACCENT_DEFAULTS.offsetMax,
      POINTER_ACCENT_DEFAULTS.offsetMax,
    ),
    blendMode: options.blendMode ?? POINTER_ACCENT_DEFAULTS.blendMode,
    zIndex: options.zIndex ?? POINTER_ACCENT_DEFAULTS.zIndex,
    className: options.className,
    hoverGrow: options.hoverGrow ?? POINTER_ACCENT_DEFAULTS.hoverGrow,
    hoverSelectors: options.hoverSelectors ?? POINTER_ACCENT_DEFAULTS.hoverSelectors,
    textSelectors: options.textSelectors ?? POINTER_ACCENT_DEFAULTS.textSelectors,
    hoverScaleMax: clamp(
      options.hoverScaleMax ?? POINTER_ACCENT_DEFAULTS.hoverScaleMax,
      POINTER_ACCENT_DEFAULTS.hoverScaleMaxMin,
      POINTER_ACCENT_DEFAULTS.hoverScaleMaxMax,
    ),
  };
}

export function pointerSpeedPxPerMs(distance: number, elapsedMs: number): number {
  if (elapsedMs <= 0) {
    return 0;
  }
  return distance / elapsedMs;
}

export function clampPointerSpeed(speed: number): number {
  return clamp(speed, 0, POINTER_ACCENT_DEFAULTS.speedMax);
}

export function pointerDeformation(
  speed: number,
  stretch: number,
  maxStretch: number,
): { scaleX: number; scaleY: number } {
  const extra = clamp(
    clampPointerSpeed(speed) * stretch,
    0,
    maxStretch,
  );
  const scaleX = 1 + extra;
  const scaleY = 1 / scaleX;
  return { scaleX, scaleY };
}

export function pointerHoverCoverScale(
  restSize: number,
  width: number,
  height: number,
  hoverScaleMax: number,
  padding = POINTER_ACCENT_DEFAULTS.hoverPadding,
): number {
  if (restSize <= 0) {
    return 1;
  }
  const needed = (Math.max(width, height) * padding) / restSize;
  return clamp(needed, 1, hoverScaleMax);
}

export function pointerAccentLayoutSize(
  restSize: number,
  hoverGrow: boolean,
  hoverScaleMax: number,
): number {
  if (!hoverGrow || hoverScaleMax <= 1) {
    return restSize;
  }
  return restSize * hoverScaleMax;
}

export function pointerAccentHoverTransform(
  coverScale: number,
  hoverGrow: boolean,
  hoverScaleMax: number,
): number {
  if (!hoverGrow || hoverScaleMax <= 0) {
    return 1;
  }
  return coverScale / hoverScaleMax;
}

export function pointerRotationDeg(dx: number, dy: number): number {
  if (dx === 0 && dy === 0) {
    return 0;
  }
  return (Math.atan2(dy, dx) * 180) / Math.PI;
}

export function pointerAccentZIndexVar(layer: PointerAccentZIndex): string {
  return `var(--z-${layer})`;
}

export const MOTION_DEFAULTS = {
  staggerInterval: 0.08,
  staggerDelay: 0,
  staggerAmount: 0.3,
  staggerOnce: true,
  staggerY: 16,
  parallaxSpeed: 0.2,
  parallaxSpeedMin: 0,
  parallaxSpeedMax: 0.45,
  parallaxRangePx: 72,
  magneticStrength: 0.35,
  magneticStrengthMin: 0,
  magneticStrengthMax: 1,
  magneticMaxOffset: 16,
  magneticMaxOffsetMin: 0,
  magneticMaxOffsetMax: 32,
  imageScale: 1,
  imageScaleMin: 1,
  imageScaleMax: 1.08,
  imageRevealY: 24,
  ease: [0.16, 1, 0.3, 1] as const,
  duration: 0.55,
};

export function clamp(value: number, min: number, max: number): number {
  return Math.min(max, Math.max(min, value));
}

export function clampParallaxSpeed(speed: number): number {
  return clamp(
    speed,
    MOTION_DEFAULTS.parallaxSpeedMin,
    MOTION_DEFAULTS.parallaxSpeedMax,
  );
}

export function clampMagneticStrength(strength: number): number {
  return clamp(
    strength,
    MOTION_DEFAULTS.magneticStrengthMin,
    MOTION_DEFAULTS.magneticStrengthMax,
  );
}

export function clampMagneticOffset(offset: number): number {
  return clamp(
    offset,
    MOTION_DEFAULTS.magneticMaxOffsetMin,
    MOTION_DEFAULTS.magneticMaxOffsetMax,
  );
}

export function clampImageScale(scale: number): number {
  return clamp(
    scale,
    MOTION_DEFAULTS.imageScaleMin,
    MOTION_DEFAULTS.imageScaleMax,
  );
}

export function clampStaggerInterval(interval: number): number {
  return clamp(interval, 0, 1);
}

export function parallaxTravelPx(speed: number): number {
  return clampParallaxSpeed(speed) * MOTION_DEFAULTS.parallaxRangePx;
}

export const FINE_POINTER_QUERY = "(pointer: fine) and (hover: hover)";

export function shouldAnimateMotion(
  reduce: boolean | null | undefined,
): boolean {
  return !reduce;
}

export function shouldEnableParallax(options: {
  reduce: boolean | null | undefined;
  viewportWidth: number | null;
  disableBelow?: number;
}): boolean {
  if (!shouldAnimateMotion(options.reduce)) {
    return false;
  }
  if (
    options.disableBelow != null &&
    options.viewportWidth != null &&
    options.viewportWidth < options.disableBelow
  ) {
    return false;
  }
  return true;
}

export function shouldEnableMagnetic(options: {
  reduce: boolean | null | undefined;
  finePointer: boolean;
  pointerType?: string;
}): boolean {
  if (!shouldAnimateMotion(options.reduce)) {
    return false;
  }
  if (!options.finePointer) {
    return false;
  }
  if (
    options.pointerType &&
    options.pointerType !== "mouse" &&
    options.pointerType !== "pen"
  ) {
    return false;
  }
  return true;
}

export function shouldEnablePointerAccent(options: {
  enabled: boolean;
  reduce: boolean | null | undefined;
  finePointer: boolean;
  pointerType?: string;
}): boolean {
  if (!options.enabled) {
    return false;
  }
  return shouldEnableMagnetic({
    reduce: options.reduce,
    finePointer: options.finePointer,
    pointerType: options.pointerType,
  });
}

"use client";

import { gsap } from "gsap";
import { CustomEase } from "gsap/CustomEase";
import { ScrollTrigger } from "gsap/ScrollTrigger";
import { useGSAP } from "@gsap/react";

let registered = false;
const plugins = [ScrollTrigger, useGSAP, CustomEase];

export function registerGsap() {
  if (registered || typeof window === "undefined") {
    return;
  }
  gsap.registerPlugin(...plugins);
  registered = true;
}

export function reducedMotionMatchMedia() {
  return gsap.matchMedia();
}

export { CustomEase, gsap, ScrollTrigger, useGSAP };

"use client";

import { createContext, useContext } from "react";
import { houseMotionProfile } from "./profiles/create-motion-profile";
import type { MotionProfile } from "./profiles/types";

export const MotionProfileContext =
  createContext<MotionProfile>(houseMotionProfile);

export function useMotionProfile(): MotionProfile {
  return useContext(MotionProfileContext);
}

import type { CubicBezier, DurationToken, MotionProfileData, TweenIntent } from "./profiles/types";

export type ResolveTweenOptions = {
  intent?: TweenIntent;
  ease?: CubicBezier;
  duration?: number;
  durationToken?: DurationToken;
};

export function toMotionEase(
  ease: CubicBezier,
): [number, number, number, number] {
  return [ease[0], ease[1], ease[2], ease[3]];
}

export function resolveTween(
  profile: MotionProfileData,
  options: ResolveTweenOptions = {},
): { duration: number; ease: CubicBezier } {
  const intent = options.intent ?? "enter";
  return {
    duration:
      options.duration ??
      profile.duration[options.durationToken ?? "base"],
    ease: options.ease ?? profile.easing[intent],
  };
}

export const TWEEN_INTENTS = [
  "enter",
  "settle",
  "move",
  "exit",
  "linear",
] as const;

export const SPRING_INTENTS = ["pop"] as const;

export const DURATION_TOKENS = ["instant", "fast", "base", "slow"] as const;

export const STAGGER_TOKENS = ["tight", "normal", "expressive"] as const;

export type TweenIntent = (typeof TWEEN_INTENTS)[number];

export type SpringIntent = (typeof SPRING_INTENTS)[number];

export type DurationToken = (typeof DURATION_TOKENS)[number];

export type StaggerToken = (typeof STAGGER_TOKENS)[number];

export type CubicBezier = readonly [number, number, number, number];

export type SpringConfig = {
  type: "spring";
  stiffness: number;
  damping: number;
  mass: number;
  velocity?: number;
};

export type MotionProfileData = {
  easing: Record<TweenIntent, CubicBezier>;
  spring: Record<SpringIntent, SpringConfig>;
  duration: Record<DurationToken, number>;
  stagger: Record<StaggerToken, number>;
};

export type MotionProfileOverride = {
  easing?: Partial<Record<TweenIntent, CubicBezier>>;
  spring?: Partial<Record<SpringIntent, Partial<SpringConfig>>>;
  duration?: Partial<Record<DurationToken, number>>;
  stagger?: Partial<Record<StaggerToken, number>>;
};

export type MotionProfile = MotionProfileData & {
  ease: (intent: TweenIntent) => CubicBezier;
  springOf: (intent?: SpringIntent) => SpringConfig;
  durationOf: (token: DurationToken) => number;
  staggerOf: (token: StaggerToken) => number;
};

export class MotionProfileError extends Error {
  constructor(message: string) {
    super(message);
    this.name = "MotionProfileError";
  }
}

import { HOUSE_MOTION_PROFILE } from "./house";
import {
  DURATION_TOKENS,
  MotionProfileError,
  SPRING_INTENTS,
  STAGGER_TOKENS,
  TWEEN_INTENTS,
  type CubicBezier,
  type MotionProfile,
  type MotionProfileData,
  type MotionProfileOverride,
  type SpringConfig,
  type TweenIntent,
} from "./types";

function isFiniteNumber(value: unknown): value is number {
  return typeof value === "number" && Number.isFinite(value);
}

export function assertCubicBezier(
  value: unknown,
  path: string,
): asserts value is CubicBezier {
  if (!Array.isArray(value) || value.length !== 4) {
    throw new MotionProfileError(
      `${path} must be a cubic Bézier of four numbers [x1, y1, x2, y2].`,
    );
  }

  const [x1, y1, x2, y2] = value;
  if (
    !isFiniteNumber(x1) ||
    !isFiniteNumber(y1) ||
    !isFiniteNumber(x2) ||
    !isFiniteNumber(y2)
  ) {
    throw new MotionProfileError(`${path} Bézier values must be finite numbers.`);
  }

  if (x1 < 0 || x1 > 1 || x2 < 0 || x2 > 1) {
    throw new MotionProfileError(
      `${path} X control points must stay between 0 and 1. Received x1=${String(x1)}, x2=${String(x2)}.`,
    );
  }
}

function assertPositive(value: unknown, path: string) {
  if (!isFiniteNumber(value) || value <= 0) {
    throw new MotionProfileError(`${path} must be a finite number greater than 0.`);
  }
}

function assertSpring(value: SpringConfig, path: string) {
  if (value.type !== "spring") {
    throw new MotionProfileError(`${path}.type must be "spring".`);
  }
  assertPositive(value.stiffness, `${path}.stiffness`);
  assertPositive(value.damping, `${path}.damping`);
  assertPositive(value.mass, `${path}.mass`);
  if (value.velocity !== undefined && !isFiniteNumber(value.velocity)) {
    throw new MotionProfileError(`${path}.velocity must be a finite number when set.`);
  }
}

export function validateMotionProfileData(
  data: MotionProfileData,
): MotionProfileData {
  for (const intent of TWEEN_INTENTS) {
    assertCubicBezier(data.easing[intent], `easing.${intent}`);
  }

  for (const intent of SPRING_INTENTS) {
    assertSpring(data.spring[intent], `spring.${intent}`);
  }

  for (const token of DURATION_TOKENS) {
    assertPositive(data.duration[token], `duration.${token}`);
  }

  for (const token of STAGGER_TOKENS) {
    assertPositive(data.stagger[token], `stagger.${token}`);
  }

  return data;
}

function copyBezier(value: CubicBezier): CubicBezier {
  return [value[0], value[1], value[2], value[3]];
}

function mergeProfile(
  base: MotionProfileData,
  overrides: MotionProfileOverride,
): MotionProfileData {
  return {
    easing: {
      enter: copyBezier(overrides.easing?.enter ?? base.easing.enter),
      settle: copyBezier(overrides.easing?.settle ?? base.easing.settle),
      move: copyBezier(overrides.easing?.move ?? base.easing.move),
      exit: copyBezier(overrides.easing?.exit ?? base.easing.exit),
      linear: copyBezier(overrides.easing?.linear ?? base.easing.linear),
    },
    spring: {
      pop: {
        type: "spring",
        stiffness: overrides.spring?.pop?.stiffness ?? base.spring.pop.stiffness,
        damping: overrides.spring?.pop?.damping ?? base.spring.pop.damping,
        mass: overrides.spring?.pop?.mass ?? base.spring.pop.mass,
        velocity: overrides.spring?.pop?.velocity ?? base.spring.pop.velocity,
      },
    },
    duration: {
      instant: overrides.duration?.instant ?? base.duration.instant,
      fast: overrides.duration?.fast ?? base.duration.fast,
      base: overrides.duration?.base ?? base.duration.base,
      slow: overrides.duration?.slow ?? base.duration.slow,
    },
    stagger: {
      tight: overrides.stagger?.tight ?? base.stagger.tight,
      normal: overrides.stagger?.normal ?? base.stagger.normal,
      expressive: overrides.stagger?.expressive ?? base.stagger.expressive,
    },
  };
}

function withRuntime(data: MotionProfileData): MotionProfile {
  const profile: MotionProfile = {
    ...data,
    ease(intent: TweenIntent) {
      return profile.easing[intent];
    },
    springOf(intent = "pop") {
      return profile.spring[intent];
    },
    durationOf(token) {
      return profile.duration[token];
    },
    staggerOf(token) {
      return profile.stagger[token];
    },
  };
  return profile;
}

export function createMotionProfile(
  overrides: MotionProfileOverride = {},
  base: MotionProfileData = HOUSE_MOTION_PROFILE,
): MotionProfile {
  return withRuntime(validateMotionProfileData(mergeProfile(base, overrides)));
}

export const houseMotionProfile = createMotionProfile();

export function serializeMotionProfile(
  profile: MotionProfileData,
): MotionProfileData {
  const validated = validateMotionProfileData(mergeProfile(HOUSE_MOTION_PROFILE, profile));
  return {
    easing: {
      enter: copyBezier(validated.easing.enter),
      settle: copyBezier(validated.easing.settle),
      move: copyBezier(validated.easing.move),
      exit: copyBezier(validated.easing.exit),
      linear: copyBezier(validated.easing.linear),
    },
    spring: {
      pop: { ...validated.spring.pop },
    },
    duration: { ...validated.duration },
    stagger: { ...validated.stagger },
  };
}

